package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * INTEREST RUN
 * CHG 17.01.2001 - rounding added after complaint from branch 0042
 */
public class InterestCalculator {

    public long monthlyInterestCents(long balanceCents, String annualRatePercent) {
        BigDecimal balance = BigDecimal.valueOf(balanceCents);
        BigDecimal rate = new BigDecimal(annualRatePercent);
        BigDecimal divisor = new BigDecimal("1200");

        // Interest = balanceCents * (rate / 100) / 12 = balanceCents * rate / 1200
        return balance.multiply(rate)
                      .divide(divisor, 0, RoundingMode.HALF_UP)
                      .longValue();
    }
}

