package com.rustybank.legacy;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * MONEY HELPERS
 * DO NOT TOUCH - used by everything
 */
public class MoneyUtil {

    public static long parseToCents(String amount) {
        if (amount == null) {
            throw new IllegalArgumentException("INVALID AMOUNT");
        }
        try {
            BigDecimal bd = new BigDecimal(amount.trim());
            if (bd.compareTo(BigDecimal.ZERO) <= 0) {
                throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
            }
            return bd.multiply(new BigDecimal("100")).setScale(0, RoundingMode.HALF_UP).longValue();
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("INVALID AMOUNT: " + amount);
        }
    }

    /** Prints an amount for the teller screen, 2 decimals. */
    public static String formatCents(long cents) {
        long whole = cents / 100;
        long frac = Math.abs(cents % 100);
        return String.format("%d.%02d", whole, frac);
    }
}

